-- One-off repair of date-only columns saved at LOCAL midnight while the app ran on a UTC+1/+2 PC
-- (22:00 or 23:00 UTC of the previous day). Those values read one day early and re-save as a
-- spurious change in the audit log. Shift them to UTC midnight of the intended day. Only rows
-- at exactly 22:00:00 / 23:00:00 are touched; real timestamps and already-correct rows are not.

UPDATE "Salary" SET "effectiveFrom" = date_trunc('day', "effectiveFrom" + interval '2 hours') WHERE "effectiveFrom" IS NOT NULL AND EXTRACT(HOUR FROM "effectiveFrom") IN (22, 23) AND EXTRACT(MINUTE FROM "effectiveFrom") = 0 AND EXTRACT(SECOND FROM "effectiveFrom") = 0;
UPDATE "ExchangeRate" SET "effectiveFrom" = date_trunc('day', "effectiveFrom" + interval '2 hours') WHERE "effectiveFrom" IS NOT NULL AND EXTRACT(HOUR FROM "effectiveFrom") IN (22, 23) AND EXTRACT(MINUTE FROM "effectiveFrom") = 0 AND EXTRACT(SECOND FROM "effectiveFrom") = 0;
UPDATE "Employment" SET "startDate" = date_trunc('day', "startDate" + interval '2 hours') WHERE "startDate" IS NOT NULL AND EXTRACT(HOUR FROM "startDate") IN (22, 23) AND EXTRACT(MINUTE FROM "startDate") = 0 AND EXTRACT(SECOND FROM "startDate") = 0;
UPDATE "Employment" SET "endDate" = date_trunc('day', "endDate" + interval '2 hours') WHERE "endDate" IS NOT NULL AND EXTRACT(HOUR FROM "endDate") IN (22, 23) AND EXTRACT(MINUTE FROM "endDate") = 0 AND EXTRACT(SECOND FROM "endDate") = 0;
