UPDATE "Milestone" SET "endDate" = date_trunc('day', "endDate" + interval '2 hours') WHERE "endDate" IS NOT NULL AND EXTRACT(HOUR FROM "endDate") IN (22, 23) AND EXTRACT(MINUTE FROM "endDate") = 0 AND EXTRACT(SECOND FROM "endDate") = 0;
