UPDATE "Assignment" SET "endDate" = date_trunc('day', "endDate" + interval '2 hours') WHERE "endDate" IS NOT NULL AND EXTRACT(HOUR FROM "endDate") IN (22, 23) AND EXTRACT(MINUTE FROM "endDate") = 0 AND EXTRACT(SECOND FROM "endDate") = 0;
-- Unique on (assignmentId, taskId, weekStartDate): skip a row whose corrected week already exists.
UPDATE "AssignmentPlan" a SET "weekStartDate" = date_trunc('day', a."weekStartDate" + interval '2 hours')
WHERE a."weekStartDate" IS NOT NULL AND EXTRACT(HOUR FROM a."weekStartDate") IN (22, 23) AND EXTRACT(MINUTE FROM a."weekStartDate") = 0 AND EXTRACT(SECOND FROM a."weekStartDate") = 0
  AND NOT EXISTS (SELECT 1 FROM "AssignmentPlan" b WHERE b."assignmentId" = a."assignmentId" AND b."taskId" IS NOT DISTINCT FROM a."taskId" AND b."weekStartDate" = date_trunc('day', a."weekStartDate" + interval '2 hours'));
UPDATE "Task" SET "startDate" = date_trunc('day', "startDate" + interval '2 hours') WHERE "startDate" IS NOT NULL AND EXTRACT(HOUR FROM "startDate") IN (22, 23) AND EXTRACT(MINUTE FROM "startDate") = 0 AND EXTRACT(SECOND FROM "startDate") = 0;
