UPDATE "TimeCard" SET "weekStartDate" = date_trunc('day', "weekStartDate" + interval '2 hours') WHERE "weekStartDate" IS NOT NULL AND EXTRACT(HOUR FROM "weekStartDate") IN (22, 23) AND EXTRACT(MINUTE FROM "weekStartDate") = 0 AND EXTRACT(SECOND FROM "weekStartDate") = 0;
-- Unique on (timeCardId, taskId, date): skip a row whose corrected day already exists on the card.
UPDATE "TimeEntry" a SET "date" = date_trunc('day', a."date" + interval '2 hours')
WHERE a."date" IS NOT NULL AND EXTRACT(HOUR FROM a."date") IN (22, 23) AND EXTRACT(MINUTE FROM a."date") = 0 AND EXTRACT(SECOND FROM a."date") = 0
  AND NOT EXISTS (SELECT 1 FROM "TimeEntry" b WHERE b."timeCardId" = a."timeCardId" AND b."taskId" IS NOT DISTINCT FROM a."taskId" AND b."date" = date_trunc('day', a."date" + interval '2 hours'));
